-- Each support district selects a TileBase by span, direction and position.
CREATE TEMP TABLE BS_OrientedSupports(Type TEXT PRIMARY KEY, Base TEXT NOT NULL);
WITH Directions(D) AS (VALUES(0),(1),(2),(3),(4),(5)),
     Segments(Span,Tile) AS (VALUES(2,2),(3,2),(3,3))
SELECT 'DISTRICT_BS_SUPPORT_' || Tile || '_N' || Span || '_D' || D,
       'DISTRICT_BS_SUPPORT_' || Tile
FROM Segments CROSS JOIN Directions;

    DistrictType, Name, PrereqTech, PrereqCivic, Coast,
    Description, Cost, RequiresPlacement, RequiresPopulation, NoAdjacentCity,
    CityCenter, Aqueduct, InternalOnly, ZOC, FreeEmbark,
    HitPoints, CaptureRemovesBuildings, CaptureRemovesCityDefenses, PlunderType, PlunderAmount,
    TradeEmbark, MilitaryDomain, CostProgressionModel, CostProgressionParam1, TraitType,
    Appeal, Housing, Entertainment, OnePerCity, AllowsHolyCity,
    Maintenance, AirSlots, CitizenSlots, TravelTime, CityStrengthModifier,
    AdjacentToLand, CanAttack, AdvisorType, CaptureRemovesDistrict, MaxPerPlayer
)
SELECT
    S.Type, D.Name, D.PrereqTech, D.PrereqCivic, D.Coast,
    D.Description, D.Cost, D.RequiresPlacement, D.RequiresPopulation, D.NoAdjacentCity,
    D.CityCenter, D.Aqueduct, D.InternalOnly, D.ZOC, D.FreeEmbark,
    D.HitPoints, D.CaptureRemovesBuildings, D.CaptureRemovesCityDefenses, D.PlunderType, D.PlunderAmount,
    D.TradeEmbark, D.MilitaryDomain, D.CostProgressionModel, D.CostProgressionParam1, D.TraitType,
    D.Appeal, D.Housing, D.Entertainment, D.OnePerCity, D.AllowsHolyCity,
    D.Maintenance, D.AirSlots, D.CitizenSlots, D.TravelTime, D.CityStrengthModifier,
    D.AdjacentToLand, D.CanAttack, D.AdvisorType, D.CaptureRemovesDistrict, D.MaxPerPlayer
FROM BS_OrientedSupports AS S JOIN Districts AS D ON D.DistrictType=S.Base;
SELECT S.Type, V.TerrainType
FROM BS_OrientedSupports AS S JOIN District_ValidTerrains AS V ON V.DistrictType=S.Base;
INSERT OR IGNORE INTO CivilopediaPageExcludes(SectionId,PageId)
SELECT 'DISTRICTS',Type FROM BS_OrientedSupports;
DROP TABLE BS_OrientedSupports;
